namespace UnityEngine {
 public class Object { public bool destroyed;public static void Destroy(Object o){if(!ReferenceEquals(o,null))o.destroyed=true;}public static bool operator ==(Object a,Object b){return (ReferenceEquals(a,null)||a.destroyed)?(ReferenceEquals(b,null)||b.destroyed):ReferenceEquals(a,b);}public static bool operator !=(Object a,Object b){return !(a==b);}public override bool Equals(object o){return ReferenceEquals(this,o);}public override int GetHashCode(){return base.GetHashCode();}}
 public struct Vector3 {public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public float magnitude{get{return (float)Math.Sqrt(x*x+y*y+z*z);}}public Vector3 normalized{get{float m=magnitude;return new Vector3(x/m,y/m,z/m);}}public static Vector3 operator -(Vector3 a){return new Vector3(-a.x,-a.y,-a.z);}public static Vector3 ProjectOnPlane(Vector3 a,Vector3 n){float dot=(a.x*n.x+a.y*n.y+a.z*n.z)/(n.x*n.x+n.y*n.y+n.z*n.z);return new Vector3(a.x-n.x*dot,a.y-n.y*dot,a.z-n.z*dot);}public static Vector3 zero {get{return new Vector3();}}public static Vector3 operator -(Vector3 a,Vector3 b){return new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);}}
 public struct Quaternion {public float angle;public static Quaternion LookRotation(Vector3 forward,Vector3 up){return new Quaternion{angle=(float)(Math.Atan2(forward.x,forward.z)*180/Math.PI)};}public static Quaternion Inverse(Quaternion a){return new Quaternion{angle=-a.angle};}public static Quaternion operator *(Quaternion a,Quaternion b){return new Quaternion{angle=a.angle+b.angle};}}
 public class Transform {public Vector3 position;public Quaternion rotation;public Vector3 InverseTransformPoint(Vector3 p){return p-position;}}
 public class GameObject:Object {public string name;public Transform transform=new Transform();public static int jointsCreated,failAfter;public static System.Collections.Generic.List<GameObject> created=new System.Collections.Generic.List<GameObject>();public GameObject(string n){name=n;created.Add(this);}public T AddComponent<T>() where T:new(){var c=new T();var rb=c as Rigidbody;if(rb!=null){rb.gameObject=this;rb.transform=transform;}if(c is FixedJoint){jointsCreated++;if(failAfter>0&&jointsCreated==failAfter)throw new Exception("injected allocation failure");}return c;}}
 public class Rigidbody:Object {public GameObject gameObject;public Transform transform;public float mass=5f;public bool isKinematic,useGravity;public Vector3 worldCenterOfMass;public Quaternion rotation;public Vector3 lastPosition;public Quaternion lastRotation;public void MovePosition(Vector3 p){lastPosition=p;transform.position=p;}public void MoveRotation(Quaternion q){lastRotation=q;}}
 public class FixedJoint:Object {public bool autoConfigureConnectedAnchor,enableCollision,enablePreprocessing;public Vector3 anchor,connectedAnchor;public Rigidbody connectedBody;public float breakForce,breakTorque;}
 public static class Debug {public static string lastError;public static void LogError(string text){lastError=text;}}public static class Time {public static float fixedDeltaTime=.02f;}
}
public struct Vector3d {public double x,y,z;public Vector3d(double a,double b,double c){x=a;y=b;z=c;}public static Vector3d operator -(Vector3d a,Vector3d b){return new Vector3d(a.x-b.x,a.y-b.y,a.z-b.z);}public double magnitude{get{return Math.Sqrt(x*x+y*y+z*z);}}public static implicit operator Vector3d(UnityEngine.Vector3 v){return new Vector3d(v.x,v.y,v.z);}public static implicit operator UnityEngine.Vector3(Vector3d v){return new UnityEngine.Vector3((float)v.x,(float)v.y,(float)v.z);}}
