public class EventOne<T> {public List<Action<T>> calls=new List<Action<T>>();public void Add(Action<T> f){calls.Add(f);}public void Remove(Action<T> f){calls.Remove(f);}public void Fire(T p){foreach(var f in calls.ToArray())f(p);}}
public class EventTwo<T,U> {public List<Action<T,U>> calls=new List<Action<T,U>>();public void Add(Action<T,U> f){calls.Add(f);}public void Remove(Action<T,U> f){calls.Remove(f);}public void Fire(T p,U q){foreach(var f in calls.ToArray())f(p,q);}}
