public class CelestialBody {public UnityEngine.Transform transform=new UnityEngine.Transform();public double shift,surfaceYaw;public double GetLatitude(Vector3d p,bool unused){double x=p.x-shift;return x*Math.Cos(surfaceYaw)-p.z*Math.Sin(surfaceYaw);}public double GetLongitude(Vector3d p,bool unused){double x=p.x-shift;return x*Math.Sin(surfaceYaw)+p.z*Math.Cos(surfaceYaw);}public double GetAltitude(Vector3d p){return p.y;}public Vector3d GetWorldSurfacePosition(double a,double b,double c){return new Vector3d(a*Math.Cos(surfaceYaw)+b*Math.Sin(surfaceYaw)+shift,c,-a*Math.Sin(surfaceYaw)+b*Math.Cos(surfaceYaw));}}
