public class VesselPrecalculate {public bool isEasingGravity;} public class Vessel {public VesselPrecalculate precalc=new VesselPrecalculate();public bool loaded=true,packed,Landed=true,Splashed;public Vector3d srf_velocity,graviticAcceleration=new Vector3d(0,-9.81,0);public CelestialBody mainBody=new CelestialBody();public FlightCtrlState ctrlState=new FlightCtrlState();public List<Part> parts=new List<Part>();public List<ModuleRWGroundTether> modules=new List<ModuleRWGroundTether>();public List<ModuleRWGroundDeploy> supports=new List<ModuleRWGroundDeploy>{new ModuleRWGroundDeploy()};public float GetTotalMass(){return 20;}public List<T> FindPartModulesImplementing<T>(){var result=new List<T>();if(typeof(T)==typeof(ModuleRWGroundTether)){foreach(var m in modules)result.Add((T)(object)m);}else{foreach(var m in supports)result.Add((T)(object)m);}return result;}}
